extends RefCounted
static var samples: Dictionary = {}
static func record(label: String, duration: int) -> void:
	if not samples.has(label):
		samples[label] = {"calls": 0, "total_us": 0, "max_us": 0}
	var entry: Dictionary = samples[label]
	entry.calls += 1
	entry.total_us += duration
	entry.max_us = maxi(entry.max_us, duration)
